"use client";

import type { AnchorHTMLAttributes } from "react";
import "./motion-link.css";

export function MotionLink({
  children,
  className = "",
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement>) {
  return (
    <a {...props} className={`forme-link ${className}`}>
      <span className="forme-link-window">
        <span className="forme-link-text">{children}</span>
        <span className="forme-link-copy" aria-hidden="true">
          {children}
        </span>
      </span>
      <span className="forme-link-arrow" aria-hidden="true">
        ↗
      </span>
    </a>
  );
}

.forme-link {
  display: inline-flex;
  align-items: center;
  gap: 24px;
  color: inherit;
  text-decoration: none;
  line-height: 1.3;
  padding: 7px 0;
  border-bottom: 1px solid currentColor;
}
.forme-link-window {
  position: relative;
  overflow: hidden;
  display: block;
}
.forme-link-text,
.forme-link-copy {
  display: block;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.forme-link-copy {
  position: absolute;
  inset: 0;
  transform: translateY(110%);
}
.forme-link:hover .forme-link-text,
.forme-link:focus-visible .forme-link-text {
  transform: translateY(-110%);
}
.forme-link:hover .forme-link-copy,
.forme-link:focus-visible .forme-link-copy {
  transform: translateY(0);
}
.forme-link-arrow {
  display: block;
  transition: transform 0.3s;
}
.forme-link:hover .forme-link-arrow {
  transform: translate(3px, -3px);
}
.forme-link:focus-visible {
  outline: 3px solid #2749ed;
  outline-offset: 5px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-link-text,
  .forme-link-copy,
  .forme-link-arrow {
    transition: none;
  }
  .forme-link:hover .forme-link-text,
  .forme-link:focus-visible .forme-link-text,
  .forme-link:hover .forme-link-arrow {
    transform: none;
  }
  .forme-link-copy {
    display: none;
  }
}
